-- MyNota · Phase 2 · map content: nodes, relations, sources, ai_jobs
-- Readable by everyone on the map; writable by the owner and editors (map_role()).
-- IDs may be generated by the client so the same ids work in IndexedDB and, later, Yjs.

-- ---------------------------------------------------------------------------
-- nodes: one flexible table; `level` says what a node is (book / chapter / section / block)
-- ---------------------------------------------------------------------------

create table public.nodes (
  id               uuid primary key default gen_random_uuid(),
  map_id           uuid not null references public.maps (id) on delete cascade,
  parent_id        uuid references public.nodes (id) on delete cascade,
  sort_order       integer not null default 0,
  level            text not null,
  title            text not null,
  summary          text not null default '',
  type             text,
  icon             text,
  color            text,
  importance       text not null default 'supporting',
  details          jsonb not null default '[]'::jsonb,
  lang             text,
  dir              text not null default 'ltr',
  branch_view      text not null default 'tree',
  position         jsonb,
  size             jsonb,
  collapsed        boolean not null default false,
  source           jsonb not null default '{"paragraphs": []}'::jsonb,
  ai_added         boolean not null default false,
  ai_added_reason  text,
  origin           text not null default 'user',
  created_by       uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),

  constraint nodes_level_valid check (level in ('book', 'chapter', 'section', 'block')),
  constraint nodes_title_length check (char_length(title) between 1 and 200),
  constraint nodes_summary_length check (char_length(summary) <= 500),
  constraint nodes_type_valid check (type is null or type in (
    'definition', 'concept', 'process_step', 'event', 'person', 'formula',
    'example', 'comparison', 'key_fact', 'warning', 'vocabulary')),
  constraint nodes_icon_length check (icon is null or char_length(icon) <= 40),
  constraint nodes_color_valid check (color is null or color in (
    'yellow', 'coral', 'sky', 'mint', 'lavender', 'pink', 'orange', 'lime')),
  constraint nodes_importance_valid check (importance in ('core', 'supporting', 'extra')),
  constraint nodes_details_array check (jsonb_typeof(details) = 'array'),
  constraint nodes_details_size check (pg_column_size(details) <= 65536),
  constraint nodes_lang_format check (lang is null or lang ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})?$'),
  constraint nodes_dir_valid check (dir in ('ltr', 'rtl')),
  constraint nodes_branch_view_valid check (branch_view in ('tree', 'process', 'timeline', 'comparison', 'cause_effect')),
  constraint nodes_position_shape check (position is null or (jsonb_typeof(position) = 'object'
    and jsonb_typeof(position -> 'x') = 'number' and jsonb_typeof(position -> 'y') = 'number')),
  constraint nodes_size_shape check (size is null or (jsonb_typeof(size) = 'object'
    and jsonb_typeof(size -> 'w') = 'number' and jsonb_typeof(size -> 'h') = 'number')),
  constraint nodes_source_shape check (jsonb_typeof(source) = 'object'
    and jsonb_typeof(source -> 'paragraphs') = 'array' and pg_column_size(source) <= 8192),
  constraint nodes_ai_added_reason_length check (ai_added_reason is null or char_length(ai_added_reason) <= 500),
  constraint nodes_origin_valid check (origin in ('user', 'ai')),
  constraint nodes_not_own_parent check (parent_id is null or parent_id <> id)
);

create index nodes_map_idx on public.nodes (map_id);
create index nodes_parent_idx on public.nodes (parent_id, sort_order);

create trigger nodes_set_updated_at
  before update on public.nodes
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- relations: labeled links between two nodes of the same map
-- ---------------------------------------------------------------------------

create table public.relations (
  id          uuid primary key default gen_random_uuid(),
  map_id      uuid not null references public.maps (id) on delete cascade,
  from_node   uuid not null references public.nodes (id) on delete cascade,
  to_node     uuid not null references public.nodes (id) on delete cascade,
  type        text not null default 'related',
  label       text not null default '',
  direction   text not null default 'forward',
  status      text not null default 'accepted',
  origin      text not null default 'user',
  created_by  uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  constraint relations_type_valid check (type in (
    'causes', 'leads_to', 'part_of', 'example_of', 'contrasts_with',
    'prerequisite', 'analogy', 'derived_from', 'related')),
  constraint relations_label_length check (char_length(label) <= 40),
  constraint relations_direction_valid check (direction in ('forward', 'backward', 'both')),
  constraint relations_status_valid check (status in ('suggested', 'accepted')),
  constraint relations_origin_valid check (origin in ('user', 'ai')),
  constraint relations_not_self check (from_node <> to_node)
);

create index relations_map_idx on public.relations (map_id);
create index relations_from_idx on public.relations (from_node);
create index relations_to_idx on public.relations (to_node);

create trigger relations_set_updated_at
  before update on public.relations
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- sources: the numbered paragraphs (P1..Pn) that blocks cite
-- ---------------------------------------------------------------------------

create table public.sources (
  id               uuid primary key default gen_random_uuid(),
  map_id           uuid not null references public.maps (id) on delete cascade,
  chapter_node_id  uuid references public.nodes (id) on delete set null,
  kind             text not null default 'text',
  storage_path     text,
  pages            integer,
  paragraphs       jsonb not null default '[]'::jsonb,
  created_by       uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at       timestamptz not null default now(),

  constraint sources_kind_valid check (kind in ('pdf', 'images', 'text')),
  constraint sources_storage_path_length check (storage_path is null or char_length(storage_path) <= 512),
  constraint sources_pages_range check (pages is null or pages between 1 and 5000),
  constraint sources_paragraphs_array check (jsonb_typeof(paragraphs) = 'array'),
  -- Roughly 2 MB of text per source; a whole book is split into one source per chapter.
  constraint sources_paragraphs_size check (pg_column_size(paragraphs) <= 2097152)
);

create index sources_map_idx on public.sources (map_id);

-- ---------------------------------------------------------------------------
-- ai_jobs: one row per AI request. NEVER stores the API key.
-- ---------------------------------------------------------------------------

create table public.ai_jobs (
  id               uuid primary key default gen_random_uuid(),
  map_id           uuid not null references public.maps (id) on delete cascade,
  chapter_node_id  uuid references public.nodes (id) on delete set null,
  node_id          uuid references public.nodes (id) on delete set null,
  pass             text not null,
  provider         text not null,
  model            text not null,
  prompt_version   text not null,
  status           text not null default 'queued',
  tokens_in        integer,
  tokens_out       integer,
  duration_ms      integer,
  error            text,
  created_by       uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),

  constraint ai_jobs_pass_valid check (pass in ('outline', 'details', 'links', 'tool')),
  constraint ai_jobs_provider_valid check (provider in ('gemini', 'anthropic', 'openai_compatible')),
  constraint ai_jobs_model_length check (char_length(model) between 1 and 100),
  constraint ai_jobs_prompt_version_length check (char_length(prompt_version) between 1 and 40),
  constraint ai_jobs_status_valid check (status in ('queued', 'running', 'done', 'failed')),
  constraint ai_jobs_numbers_positive check (
    coalesce(tokens_in, 0) >= 0 and coalesce(tokens_out, 0) >= 0 and coalesce(duration_ms, 0) >= 0),
  constraint ai_jobs_error_length check (error is null or char_length(error) <= 1000),
  -- Defense in depth: refuse anything that looks like a provider key in the error text.
  constraint ai_jobs_error_no_keys check (error is null or (
    error !~ 'AIza[0-9A-Za-z_-]{20,}' and error !~ 'sk-[A-Za-z0-9_-]{16,}'))
);

create index ai_jobs_map_idx on public.ai_jobs (map_id, created_at desc);

create trigger ai_jobs_set_updated_at
  before update on public.ai_jobs
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Integrity guards
-- ---------------------------------------------------------------------------

-- map_id never moves; parents, relation ends and chapter links stay inside the same map;
-- a node can never become its own ancestor.
create or replace function public.map_content_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  depth int := 0;
  cursor_id uuid;
begin
  if tg_op = 'UPDATE' and new.map_id is distinct from old.map_id then
    raise exception 'map_id cannot be changed' using errcode = '42501';
  end if;

  if tg_table_name = 'nodes' then
    if new.parent_id is not null then
      if not exists (select 1 from public.nodes p where p.id = new.parent_id and p.map_id = new.map_id) then
        raise exception 'parent belongs to another map' using errcode = '23503';
      end if;
      if tg_op = 'UPDATE' and new.parent_id is distinct from old.parent_id then
        cursor_id := new.parent_id;
        while cursor_id is not null loop
          if cursor_id = new.id then
            raise exception 'a node cannot be moved under itself' using errcode = '23514';
          end if;
          depth := depth + 1;
          if depth > 64 then raise exception 'map is too deep' using errcode = '23514'; end if;
          select p.parent_id into cursor_id from public.nodes p where p.id = cursor_id;
        end loop;
      end if;
    end if;
  elsif tg_table_name = 'relations' then
    if (select count(*) from public.nodes n
        where n.id in (new.from_node, new.to_node) and n.map_id = new.map_id) <> 2 then
      raise exception 'both ends of a relation must be in the same map' using errcode = '23503';
    end if;
  elsif tg_table_name in ('sources', 'ai_jobs') then
    if new.chapter_node_id is not null and not exists (
      select 1 from public.nodes n where n.id = new.chapter_node_id and n.map_id = new.map_id
    ) then
      raise exception 'chapter belongs to another map' using errcode = '23503';
    end if;
  end if;

  return null;
end;
$$;

-- Constraint (AFTER) triggers run at the end of the statement, so a whole map saved in one
-- multi-row insert (parents and children together) is checked with all its rows visible.
create constraint trigger nodes_guard after insert or update on public.nodes
  for each row execute function public.map_content_guard();
create constraint trigger relations_guard after insert or update on public.relations
  for each row execute function public.map_content_guard();
create constraint trigger sources_guard after insert or update on public.sources
  for each row execute function public.map_content_guard();
create constraint trigger ai_jobs_guard after insert or update on public.ai_jobs
  for each row execute function public.map_content_guard();

-- Editing a map's content bumps maps.updated_at (at most every few seconds) so the
-- library can sort by "recently edited".
create or replace function public.touch_map()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  target uuid := case when tg_op = 'DELETE' then old.map_id else new.map_id end;
begin
  update public.maps set updated_at = now()
  where id = target and updated_at < now() - interval '5 seconds';
  return null;
end;
$$;

create trigger nodes_touch_map after insert or update or delete on public.nodes
  for each row execute function public.touch_map();
create trigger relations_touch_map after insert or update or delete on public.relations
  for each row execute function public.touch_map();

-- ---------------------------------------------------------------------------
-- Privileges and Row Level Security
-- ---------------------------------------------------------------------------

alter table public.nodes enable row level security;
alter table public.relations enable row level security;
alter table public.sources enable row level security;
alter table public.ai_jobs enable row level security;

revoke all on public.nodes, public.relations, public.sources, public.ai_jobs from anon, authenticated;

grant select, insert, update, delete on public.nodes to authenticated;
grant select, insert, update, delete on public.relations to authenticated;
grant select, insert, delete on public.sources to authenticated;
grant select, insert on public.ai_jobs to authenticated;
grant update (status, tokens_in, tokens_out, duration_ms, error) on public.ai_jobs to authenticated;

-- nodes
create policy "nodes: everyone on the map reads" on public.nodes for select to authenticated
  using (public.map_role(map_id) is not null);
create policy "nodes: owner and editors add" on public.nodes for insert to authenticated
  with check (public.map_role(map_id) in ('owner', 'editor'));
create policy "nodes: owner and editors change" on public.nodes for update to authenticated
  using (public.map_role(map_id) in ('owner', 'editor'))
  with check (public.map_role(map_id) in ('owner', 'editor'));
create policy "nodes: owner and editors delete" on public.nodes for delete to authenticated
  using (public.map_role(map_id) in ('owner', 'editor'));

-- relations
create policy "relations: everyone on the map reads" on public.relations for select to authenticated
  using (public.map_role(map_id) is not null);
create policy "relations: owner and editors add" on public.relations for insert to authenticated
  with check (public.map_role(map_id) in ('owner', 'editor'));
create policy "relations: owner and editors change" on public.relations for update to authenticated
  using (public.map_role(map_id) in ('owner', 'editor'))
  with check (public.map_role(map_id) in ('owner', 'editor'));
create policy "relations: owner and editors delete" on public.relations for delete to authenticated
  using (public.map_role(map_id) in ('owner', 'editor'));

-- sources (immutable once written; replaced by delete + insert)
create policy "sources: everyone on the map reads" on public.sources for select to authenticated
  using (public.map_role(map_id) is not null);
create policy "sources: owner and editors add" on public.sources for insert to authenticated
  with check (public.map_role(map_id) in ('owner', 'editor'));
create policy "sources: owner and editors delete" on public.sources for delete to authenticated
  using (public.map_role(map_id) in ('owner', 'editor'));

-- ai_jobs: owner and editors see the map's jobs; each person updates only their own.
create policy "ai_jobs: owner and editors read" on public.ai_jobs for select to authenticated
  using (public.map_role(map_id) in ('owner', 'editor'));
create policy "ai_jobs: owner and editors record their own" on public.ai_jobs for insert to authenticated
  with check (created_by = (select auth.uid()) and public.map_role(map_id) in ('owner', 'editor'));
create policy "ai_jobs: author updates status" on public.ai_jobs for update to authenticated
  using (created_by = (select auth.uid()) and public.map_role(map_id) in ('owner', 'editor'))
  with check (created_by = (select auth.uid()));

revoke execute on function public.map_content_guard() from public, anon, authenticated;
revoke execute on function public.touch_map() from public, anon, authenticated;
